 <div class=\"item-img-wrap\">\n        <img\n          :src=\"getItemImage(item.name)\"\n          :alt=\"item.name\"\n          class=\"item-img\"\n          loading=\"lazy\"\n        />\n        <!-- 交互数量角标 -->\n        <div v-if=\"item.interactions && item.interactions.length > 0\" class=\"item-badge\">\n          {{ item.interactions.length }}\n        </div>\n      </div>\n      <div class=\"item-info\">\n        <div class=\"item-name\">{{ item.name }}</div>\n        <div class=\"item-keywords\">{{ getItemKeywords(item.name) }}</div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { ItemData } from '../schema';\nimport { ITEM_IMAGES, ITEM_KEYWORDS, DEFAULT_ITEM_IMAGE } from '../items';\n\ndefineProps<{\n  items: ItemData[];\n  isMobile?: boolean;\n  emptyText?: string;\n}>();\n\ndefineEmits<{\n  select: [item: ItemData];\n}>();\n\nfunction getItemImage(name: string): string {\n  return ITEM_IMAGES[name] || DEFAULT_ITEM_IMAGE;\n}\n\nfunction getItemKeywords(name: string): string {\n  return ITEM_KEYWORDS[name] || '';\n}\n</script>\n\n<style scoped>\n.item-grid {\n  flex: 1;\n  overflow-y: auto;\n  padding: 12px 16px;\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));\n  gap: 10px;\n  align-content: start;\n}\n\n.item-grid.is-mobile {\n  padding: 8px;\n  grid-template-columns: repeat(auto-fill, minmax(84px, 1fr));\n  gap: 6px;\n}\n\n.item-grid::-webkit-scrollbar {\n  width: 3px;\n}\n\n.item-grid::-webkit-scrollbar-thumb {\n  background: rgba(255, 255, 255, 0.1);\n  border-radius: 2px;\n}\n\n.empty-hint {\n  grid-column: 1 / -1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 40px 0;\n  gap: 10px;\n}\n\n.empty-icon-wrap {\n  opacity: 0.5;\n}\n\n.empty-text {\n  font-size: 14px;\n  color: rgba(255, 255, 255, 0.3);\n}\n\n.item-card {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  cursor: pointer;\n  transition: transform 0.2s ease;\n  padding: 5px;\n  border-radius: 10px;\n}\n\n.item-card:hover {\n  transform: scale(1.04);\n  background: rgba(255, 255, 255, 0.04);\n}\n\n.item-card:active {\n  transform: scale(0.98);\n}\n\n.item-img-wrap {\n  position: relative;\n  width: 96px;\n  height: 96px;\n  border-radius: 10px;\n  overflow: hidden;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  background: rgba(15, 20, 30, 0.6);\n  transition: border-color 0.2s, box-shadow 0.2s;\n}\n\n.is-mobile .item-img-wrap {\n  width: 66px;\n  height: 66px;\n  border-radius: 8px;\n}\n\n.item-card:hover .item-img-wrap {\n  border-color: rgba(200, 170, 110, 0.4);\n  box-shadow: 0 0 12px rgba(200, 170, 110, 0.15);\n}\n\n.item-img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n}\n\n.item-badge {\n  position: absolute;\n  top: 4px;\n  right: 4px;\n  min-width: 18px;\n  height: 18px;\n  border-radius: 9px;\n  background: rgba(200, 170, 110, 0.85);\n  color: #1a1f2e;\n  font-size: 10px;\n  font-weight: 700;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0 4px;\n  line-height: 1;\n}\n\n.item-info {\n  margin-top: 6px;\n  text-align: center;\n  max-width: 104px;\n}\n\n.is-mobile .item-info {\n  max-width: 72px;\n}\n\n.item-name {\n  font-size: 13px;\n  color: rgba(255, 255, 255, 0.75);\n  font-weight: 500;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  line-height: 1.3;\n}\n\n.is-mobile .item-name {\n  font-size: 10px;\n}\n\n.item-card:hover .item-name {\n  color: rgba(255, 255, 255, 0.95);\n}\n\n.item-keywords {\n  font-size: 10px;\n  color: rgba(255, 255, 255, 0.3);\n  line-height: 1.3;\n  margin-top: 2px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.is-mobile .item-keywords {\n  font-size: 8px;\n}\n\n.item-card:hover .item-keywords {\n  color: rgba(255, 255, 255, 0.45);\n}\n</style>\n"],"sourceRoot":""}]);
